import meter1 from "../assets/img/meter1.svg";
import meter2 from "../assets/img/meter2.svg";
import meter3 from "../assets/img/meter3.svg";
import Carousel from 'react-multi-carousel';
import 'react-multi-carousel/lib/styles.css';
import arrow1 from "../assets/img/arrow1.svg";
import arrow2 from "../assets/img/arrow2.svg";
import colorSharp from "../assets/img/color-sharp.png"
import { Windows } from "react-bootstrap-icons";

export const Skills = () => {
  const responsive = {
    superLargeDesktop: { breakpoint: { max: 4000, min: 3000 }, items: 5 },
    desktop: { breakpoint: { max: 3000, min: 1024 }, items: 3 },
    tablet: { breakpoint: { max: 1024, min: 464 }, items: 2 },
    mobile: { breakpoint: { max: 464, min: 0 }, items: 1 },
  };

  const skillCategories = [
    {
      title: "Full-Stack Development",
      skills: ["HTML", "CSS", "JavaScript", "React.js", "Django", "REST APIs"],
    },
    {
      title: "Machine Learning",
      skills: ["Python", "NumPy", "Pandas", "Scikit-learn", "PyTorch", "Matplotlib"],
    },
    {
      title: "Git & Version Control",
      skills: ["Git", "GitHub", "Branching", "Merging", "Pull Requests"],
    },
    {
      title: "Agile Development",
      skills: ["Scrum", "Kanban", "JIRA", "Standups", "Sprints"],
    },
    {
      title: "Cybersecurity",
      skills: ["Wireshark", "TCPDump", "Linux", "TCP/IP", "PowerShell"],
    },
  ];

  return (
    <section className="skill" id="skills">
      <div className="container">
        <h2>Skills</h2>

        {/* Glass container */}
        <div className="glass-container">
          <Carousel
            responsive={responsive}
            infinite={true}
            className="skill-slider"
          >
            {skillCategories.map((category) => (
              <div className="skill-box" key={category.title}>
                <h3>{category.title}</h3>
                <div className="skill-bubbles">
                  {category.skills.map((skill) => (
                    <span className="skill-bubble" key={skill}>
                      {skill}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </Carousel>
        </div>
      </div>
      <img className="background-image-left" src={colorSharp} alt="Background" />
    </section>
  );
};